// ── Helper Functions ──────────────────────────────────────

/** Returns all flashcards across all chapters */
export function getAllCards() {
  return chapters.flatMap((ch) => ch.cards);
}

/** Returns flashcards for a specific chapter number */
export function getCardsByChapter(chapterNum: number) {
  const chapter = chapters.find((ch) => ch.chapter === chapterNum);
  return chapter?.cards ?? [];
}

/** Filters cards by term or definition matching the query (case-insensitive) */
export function searchCards(query: string) {
  const q = query.toLowerCase();
  return getAllCards().filter(
    (card) =>
      card.term.toLowerCase().includes(q) ||
      card.definition.toLowerCase().includes(q),
  );
}

/** Returns chapter info without cards, including a cardCount field */
export function getChapterList() {
  return chapters.map(({ cards, ...rest }) => ({
    ...rest,
    cardCount: cards.length,
  }));
}

